<?php $isHost=$admin||$booking['mentor_id']===$this->actor['user_id'];$future=(int)$booking['starts_at']>time();$active=in_array($booking['state'],['pending','confirmed'],true); ?>
<a class="reading-back" href="<?= $this->h($this->url($admin?'/bookings':'/sessions')) ?>"><?= $this->icon('arrow') ?>درخواست‌ها و جلسات</a><header class="schedule-heading"><span class="booking-badge state-<?= $this->h($booking['state']) ?>"><?= $this->status($booking['state']) ?></span><h1><?= $this->h($booking['subject']??'درخواست مشاوره') ?></h1></header>
<div class="schedule-grid"><div><section class="card schedule-card"><div class="booking-people"><div><small>مرشد</small><strong><?= $this->h($booking['mentor_name']) ?></strong></div><div><small>درخواست‌دهنده</small><strong><?= $this->h($booking['user_name']) ?></strong></div></div><div class="booking-time"><?= $this->icon('calendar') ?><time data-timestamp="<?= (int)$booking['starts_at'] ?>"><?= $this->h(gmdate('Y-m-d H:i',(int)$booking['starts_at'])) ?> UTC</time><span>تا</span><time data-timestamp="<?= (int)$booking['ends_at'] ?>"><?= $this->h(gmdate('H:i',(int)$booking['ends_at'])) ?> UTC</time></div><p class="small muted">به وقت تهران · مشاوره رایگان</p><?php if(!empty($booking['experience_title'])): ?><p>تجربهٔ مرتبط: <?= $this->h($booking['experience_title']) ?></p><?php endif; ?><h2>شرح نیاز</h2><div class="reading-copy"><?= $this->paragraphs($booking['problem']) ?></div><?php if($booking['state']==='pending'): ?><p class="notice">منتظر پاسخ مرشد؛ مهلت پاسخ <time data-timestamp="<?= (int)$booking['expires_at'] ?>"><?= $this->h(gmdate('Y-m-d H:i',(int)$booking['expires_at'])) ?></time>. پس از پایان مهلت، زمان آزاد می‌شود.</p><?php endif; ?></section>
<?php if(($active&&$future)||($booking['state']==='confirmed'&&$isHost&&(int)$booking['ends_at']<=time())): ?><section class="card schedule-card section"><h2>پیگیری درخواست</h2><?= $this->start('/booking/action') ?><input type="hidden" name="id" value="<?= $this->h($booking['id']) ?>"><?= $this->field('note','توضیح یا دلیل لغو (اختیاری)','text','',false,1000) ?><div class="schedule-actions"><?php if($booking['state']==='pending'&&$isHost&&$future): ?><?php if(!$admin): ?><button name="action" value="accept">تأیید جلسه</button><?php endif; ?><button class="secondary" name="action" value="reject">رد درخواست</button><?php endif;if($active&&$future): ?><button class="secondary" name="action" value="cancel">لغو جلسه</button><?php endif;if($booking['state']==='confirmed'&&$isHost&&(int)$booking['ends_at']<=time()): ?><button name="action" value="complete">ثبت برگزارشدن جلسه</button><?php endif; ?></div></form></section><?php endif; ?>
<?php if(!$admin&&$booking['state']==='confirmed'&&$future): ?><details class="card schedule-card section"><summary>درخواست تغییر زمان</summary><p>زمان قبلی تا پذیرش طرف مقابل حفظ می‌شود. زمان پیشنهادی باید در برنامهٔ آزاد مرشد باشد.</p><?= $this->start('/booking/propose') ?><input type="hidden" name="id" value="<?= $this->h($booking['id']) ?>"><?= $this->field('starts_local','روز و ساعت پیشنهادی به وقت تهران','datetime-local') ?><button>ارسال پیشنهاد</button></form></details><?php endif; ?>
<?php foreach($proposals as $p): ?><article class="card schedule-card section"><h3>پیشنهاد تغییر زمان</h3><time data-timestamp="<?= (int)$p['starts_at'] ?>"><?= $this->h(gmdate('Y-m-d H:i',(int)$p['starts_at'])) ?> UTC</time><p><?= $this->status($p['state']) ?></p><?php if(!$admin&&$p['state']==='pending'&&$p['proposer_id']!==$this->actor['user_id']): ?><?= $this->start('/booking/answer') ?><input type="hidden" name="id" value="<?= $this->h($booking['id']) ?>"><input type="hidden" name="proposal_id" value="<?= $this->h($p['id']) ?>"><div class="schedule-actions"><button name="accept" value="1">پذیرش زمان جدید</button><button class="secondary" name="accept" value="0">رد پیشنهاد</button></div></form><?php endif; ?></article><?php endforeach; ?>
</div><aside><section class="card schedule-card consultation-room"><span class="service-icon"><?= $this->icon('chat') ?></span><h2>اتاق مشاوره</h2><p>روش درخواستی: <?= $this->h(['audio'=>'تماس صوتی','video'=>'تماس تصویری','chat'=>'چت آنلاین'][$booking['requested_method']??'audio']) ?></p><p class="small muted">ورود به اتاق پس از آماده‌شدن زیرساخت ارتباط و نزدیک‌شدن زمان جلسه فعال می‌شود.</p><button disabled>ورود به جلسه · به‌زودی</button></section><section class="card schedule-card section"><h2>تاریخچهٔ درخواست</h2><ol class="booking-events"><?php foreach($events as $e): ?><li><strong><?= $this->h(['internal_created'=>'ثبت درخواست','time_proposed'=>'پیشنهاد تغییر زمان','time_changed'=>'تغییر زمان تأیید شد','time_rejected'=>'رد پیشنهاد زمان','proposal_expired'=>'انقضای پیشنهاد'][$e['event']]??$this->status($e['event'])) ?></strong><time data-timestamp="<?= (int)$e['created_at'] ?>"><?= $this->h(gmdate('Y-m-d H:i',(int)$e['created_at'])) ?></time><?php if($e['note']): ?><p><?= $this->h($e['note']) ?></p><?php endif; ?></li><?php endforeach; ?></ol></section></aside></div>
